#!/usr/bin/env python3
from __future__ import annotations
import html,json,collections
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
HEALTH=ROOT/'reports'/'editorial'/'pipeline-health.json'; READY=ROOT/'reports'/'editorial'/'production-readiness.json'; ANALYTICS=ROOT/'reports'/'editorial'/'editorial-analytics.json'; COLUMN_EVENTS=ROOT/'reports'/'editorial'/'column-review-events.json'; OUT=ROOT/'docs'/'kontrolrum'/'index.html'
def e(x):return html.escape(str(x or ''),quote=True)
def load(p,d):
 if not p.exists():return d
 try:return json.loads(p.read_text(encoding='utf-8'))
 except Exception:return d
def badge(status):
 s=str(status or 'ukendt');cls='ok' if s.lower() in {'published','pass','green'} else ('warn' if s.lower() in {'checking','editing','researching','ready','scheduled','revise','yellow'} else ('bad' if s.lower() in {'escalate','rejected','failed','red'} else 'muted'));return f'<span class="badge {cls}">{e(s)}</span>'
def main():
 data=load(HEALTH,{'generated_at':None,'articles':[]});ready=load(READY,{'status':'ukendt','hard_failures':[],'warnings':[],'metrics':{}});analytics=load(ANALYTICS,{})
 arts=data.get('articles') or [];events=(load(COLUMN_EVENTS,{'events':[]}).get('events') or [])
 published=sum(1 for a in arts if a.get('status')=='published');active=sum(1 for a in arts if a.get('status') in {'researching','checking','editing','ready','scheduled'});blocked=sum(1 for a in arts if a.get('reasons'));attention=[x for x in events if str(x.get('status') or '').upper() in {'REVISE','ESCALATE'}]
 stage_counts=collections.Counter(str(a.get('resume_from') or a.get('status') or 'ukendt') for a in arts if a.get('status')!='published');reason_counts=collections.Counter()
 for a in arts:
  for reason in a.get('reasons') or []:reason_counts[str(reason).split(':',1)[0].strip()]+=1
 rows=[]
 for a in sorted(arts,key=lambda x:(0 if x.get('reasons') else 1,str(x.get('title') or ''))):
  reasons='<br>'.join(e(x) for x in a.get('reasons') or []) or '—';rows.append(f'<tr><td><strong>{e(a.get("title") or a.get("slug"))}</strong><small>{e(a.get("slug"))}</small></td><td>{badge(a.get("status"))}</td><td>{e(a.get("resume_from") or "—")}</td><td>{reasons}</td></tr>')
 stage_html=''.join(f'<li><span>{e(k)}</span><b>{v}</b></li>' for k,v in stage_counts.most_common()) or '<li><span>Ingen aktive artikler</span><b>0</b></li>';reason_html=''.join(f'<li><span>{e(k)}</span><b>{v}</b></li>' for k,v in reason_counts.most_common(8)) or '<li><span>Ingen stopårsager</span><b>0</b></li>'
 flags=[('Hård fejl',x,'bad') for x in ready.get('hard_failures') or []]+[('Advarsel',x,'warn') for x in ready.get('warnings') or []];flag_html=''.join(f'<li><span>{badge("red" if c=="bad" else "yellow")} <strong>{e(k)}</strong> {e(v)}</span></li>' for k,v,c in flags) or '<li><span>Ingen readiness-flags</span></li>'
 mix=analytics.get('category_mix') or {};mix_html=''.join(f'<li><span>{e(k)}</span><b>{v}</b></li>' for k,v in list(mix.items())[:10]) or '<li><span>Ingen data endnu</span><b>0</b></li>'
 m=ready.get('metrics') or {};dup=len(m.get('possible_duplicate_pairs') or []);sourceflags=len(m.get('source_independence_flags') or []);a11y=len(m.get('accessibility_flags') or []);perf=len(m.get('performance_flags') or [])
 page=f'''<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Kontrolrum – Morgentidende</title><style>:root{{--paper:#f8f5ef;--ink:#161513;--muted:#6f6a62;--dark:#1b2430;--rule:#d8d2c8;--ok:#e7f3e9;--warn:#fff2cc;--bad:#f8ded9}}*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,sans-serif}}header{{background:var(--dark);color:white;padding:18px 24px}}header .inner{{max-width:1180px;margin:auto;display:flex;justify-content:space-between}}header a{{color:#fff}}main{{max-width:1180px;margin:auto;padding:28px 22px 60px}}h1{{font:600 42px Georgia,serif;margin:0 0 8px}}h2{{font:600 28px Georgia,serif;margin:34px 0 12px}}.intro{{color:var(--muted);max-width:850px}}.cards{{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:26px 0}}.card,.panel{{background:#fff;border:1px solid var(--rule);padding:18px}}.card b{{display:block;font-size:30px}}.two{{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:14px 0 28px}}.metric-list{{list-style:none;margin:0;padding:0}}.metric-list li{{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid #eee}}table{{width:100%;border-collapse:collapse;background:#fff;border:1px solid var(--rule)}}th,td{{text-align:left;padding:13px 12px;border-bottom:1px solid var(--rule);vertical-align:top}}td small{{display:block;color:var(--muted);margin-top:4px}}.badge{{display:inline-block;padding:4px 8px;border-radius:999px;background:#eee;font-weight:700;font-size:12px}}.badge.ok{{background:var(--ok)}}.badge.warn{{background:var(--warn)}}.badge.bad{{background:var(--bad)}}@media(max-width:760px){{.cards{{grid-template-columns:1fr 1fr}}.two{{grid-template-columns:1fr}}table,thead,tbody,tr,th,td{{display:block}}thead{{display:none}}}}</style></head><body><header><div class="inner"><strong>Morgentidende · Kontrolrum</strong><a href="../">Til avisen</a></div></header><main><h1>Maskinrummet</h1><p class="intro">Pipeline, produktionskvalitet, kildeuafhængighed og læseroplevelse samlet ét sted.</p><div class="cards"><div class="card"><b>{published}</b><span>publiceret</span></div><div class="card"><b>{active}</b><span>aktive</span></div><div class="card"><b>{blocked}</b><span>blokerede</span></div><div class="card"><b>{len(attention)}</b><span>kronikker</span></div><div class="card"><b>{badge(ready.get('status'))}</b><span>production readiness</span></div></div><div class="two"><section class="panel"><h2 style="margin-top:0">Aktive trin</h2><ul class="metric-list">{stage_html}</ul></section><section class="panel"><h2 style="margin-top:0">Stopårsager</h2><ul class="metric-list">{reason_html}</ul></section></div><div class="two"><section class="panel"><h2 style="margin-top:0">Readiness-flags</h2><ul class="metric-list">{flag_html}</ul></section><section class="panel"><h2 style="margin-top:0">Redaktionel blanding</h2><ul class="metric-list">{mix_html}</ul></section></div><div class="cards"><div class="card"><b>{dup}</b><span>mulige dubletter</span></div><div class="card"><b>{sourceflags}</b><span>kildeflags</span></div><div class="card"><b>{a11y}</b><span>tilgængelighedsflags</span></div><div class="card"><b>{perf}</b><span>performanceflags</span></div><div class="card"><b>{e(analytics.get('unique_source_hosts') or 0)}</b><span>unikke kildedomæner</span></div></div><h2>Artikler i pipeline</h2><table><thead><tr><th>Artikel</th><th>Status</th><th>Fortsæt fra</th><th>Diagnose</th></tr></thead><tbody>{''.join(rows)}</tbody></table><p class="intro">Senest genereret: {e(data.get('generated_at') or 'ikke endnu')}</p></main></body></html>'''
 OUT.parent.mkdir(parents=True,exist_ok=True);OUT.write_text(page,encoding='utf-8');print('Control room built')
if __name__=='__main__':main()
